export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const when=s=>new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
export function conversation(messages){return messages.map(m=>`<article class="customer-message ${esc(m.role)} ${m.kind==='internal'?'internal':''}"><header><strong>${m.kind==='internal'?'Private admin note':({'customer':'You / customer','merchant':'Merchant · human reply','automatic':'Automatic update','ai-assisted':'AI-assisted · reviewed by merchant'}[m.role]||'Update')}</strong><time>${esc(when(m.at))}</time></header><p>${esc(m.text)}</p></article>`).join('');}
export async function request(path,body){let r;try{r=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});}catch{throw Error('Connection interrupted. Your request may have been saved. Retry with the same message, or refresh to check.');}const data=await r.json();if(!r.ok){const e=Error(data.error||'The request could not be completed.');e.rejected=true;throw e;}return data;}
